def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find a uniform divider, preferring one that splits the grid into equal-sized panels.
    candidates = []
    for r, row in enumerate(grid):
        if all(v == row[0] for v in row):
            candidates.append((abs(r - (h - 1 - r)), 0, r))
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            candidates.append((abs(c - (w - 1 - c)), 1, c))

    if candidates:
        _, axis, i = min(candidates)
        if axis == 0:
            top, bottom = grid[:i], grid[i + 1:]
            n = min(len(top), len(bottom))
            return [[2 if top[r][c] != 0 and bottom[r][c] != 0 else 0
                     for c in range(w)] for r in range(n)]
        left = [row[:i] for row in grid]
        right = [row[i + 1:] for row in grid]
        n = min(len(left[0]), len(right[0]))
        return [[2 if left[r][c] != 0 and right[r][c] != 0 else 0
                 for c in range(n)] for r in range(h)]

    return [[0 for _ in row] for row in grid]
